function resultModal(out,final=false){const names=room?.teams||teams,win=out.winner!==null?names[out.winner]:'Hai đội hòa điểm',myteam=match?.players.find(p=>p.id===me)?.team;modal(`<span class="badge">${final?'KẾT THÚC GIẢI ĐẤU':'KẾT THÚC TRẬN ĐẤU'}</span><div class="trophy">♜</div><div class="result-title">${esc(win)}</div><p style="text-align:center">${out.winner===null?'Điểm tổng và điểm kiến thức bằng nhau. MC cần phân định.':myteam===out.winner?'Đội của bạn đã chiến thắng!':'Chúc mừng đội chiến thắng!'}<br>MVP: <b>${esc(out.mvp)}</b></p><table class="result-table"><thead><tr><th>ĐỘI</th><th>CHIẾN ĐẤU</th><th>TRI THỨC</th><th>ĐIỂM TỔNG</th></tr></thead><tbody>${out.scores.map(s=>`<tr><td>${esc(names[s.team])}${s.correct===Math.max(...out.scores.map(x=>x.correct))?' ✧':''}</td><td>${s.combat.toFixed(1)}</td><td>${s.learning.toFixed(1)}</td><td>${s.total.toFixed(2)}</td></tr>`).join('')}</tbody></table><p class="smalltext">✧ Huy hiệu tri thức: đội có nhiều câu trả lời đúng nhất.<br>Điểm chiến đấu và tri thức được quy về thang 100 trước khi tính 50–50.</p><button class="primary" id="resultBack">${owner?'Về màn hình MC':'Về sảnh'}</button>${mode==='demo'?'<button class="textbtn" id="resultReplay">Chơi thử lại →</button>':''}`);$('#resultBack').onclick=()=>{closeModal();if(owner){mode='mc';showMC();}else{mode='lobby';resetLobby();}};if($('#resultReplay'))$('#resultReplay').onclick=startDemo;}
$('#shop').onclick=()=>{const p=match?.players.find(p=>p.id===me);if(!p)return;if(mode==='demo')demoPaused=true;modal(`<span class="badge">CỬA HÀNG TRI THỨC</span><h2>Trang bị cho hành trình.</h2><p>Ví hiện có: ${p.wallet??p.knowledge} điểm. Mỗi trang bị mua một lần/trận. Mua bằng ví thưởng; điểm xếp hạng vẫn được giữ nguyên.</p><div class="guide-grid"><div><b>✧ Trượng tinh tú</b>+5 sát thương mỗi đòn<br><button class="outline" data-buy="power">Mua · 200 điểm</button></div><div><b>⬡ Khiên học viện</b>+80 khiên hấp thụ<br><button class="outline" data-buy="shield">Mua · 200 điểm</button></div></div>`);$$('[data-buy]').forEach(b=>b.onclick=()=>{const item=b.dataset.buy;if(mode==='demo'){if((p.wallet??p.knowledge)<200||p.items.includes(item)){toast('Chưa đủ điểm hoặc đã sở hữu.');return;}p.wallet-=200;p.items.push(item);if(item==='shield')p.shield+=80;toast('Đã nhận trang bị!');closeModal();}else socket.emit('buy',{item},r=>{toast(r.error||'Đã nhận trang bị!');if(!r.error)closeModal();});});};
const bgm=new Audio();bgm.loop=true;bgm.volume=customization.music.volume;let musicMode='';function toggleSound(){soundOn=!soundOn;if(soundOn){audio??=new(window.AudioContext||window.webkitAudioContext)();audio.resume();beep(440,.15);updateMusic(true);}else{bgm.pause();audio?.suspend();}$('#sound').textContent=soundOn?'♫':'♪';$('#musicGame').textContent=soundOn?'♫ Nhạc bật':'♪ Nhạc tắt';$('#sound').setAttribute('aria-label',soundOn?'Tắt âm thanh':'Bật âm thanh');toast(soundOn?'Đã bật nhạc và âm thanh':'Đã tắt âm thanh');}$('#sound').onclick=toggleSound;$('#musicGame').onclick=toggleSound;function updateMusic(force=false){if(!soundOn)return;const which=['demo','online','spectate'].includes(mode)?'battle':'lobby';if(which!==musicMode||force){musicMode=which;const source=customization.music[which];if(bgm.getAttribute('src')!==source)bgm.src=source;if(!document.hidden)bgm.play().catch(()=>toast('Bấm nút nhạc để phát âm thanh.'));}}
function beep(freq=440,duration=.1,volume=.025){if(!soundOn||!audio)return;const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.value=freq;g.gain.setValueAtTime(volume,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+duration);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+duration);}
