async function api(url,body,method){const r=await fetch(url,{method:method||(body?'POST':'GET'),headers:{'Content-Type':'application/json',...(authed?{Authorization:'Bearer '+authed.token}:{})},...(body?{body:JSON.stringify(body)}:{})});let v;try{v=await r.json();}catch{throw Error('Chưa kết nối được máy chủ. Hãy tải lại trang và thử lại.');}if(!r.ok)throw Error(v.error||'Không thực hiện được thao tác.');return v;}
