async function becomeGuest(name){const value=await api('/api/guest',{nickname:name,resumeToken:authed?.role==='guest'?authed.token:null});authed=value;localStorage.setItem(identityKey,JSON.stringify(value));accountUI();return value;}
async function becomeHost(){const value=await api('/api/host',{nickname:'MC',resumeToken:authed?.role==='host'?authed.token:null});authed=value;localStorage.setItem(identityKey,JSON.stringify(value));accountUI();return value;}
function login(next){if(hostEdition){openMC();return;}if(authed&&next){next();return;}modal(`<span class="badge">CHỈ CẦN BIỆT DANH</span><h2>Bạn tên gì nè?</h2><p>Không cần tài khoản hoặc mật khẩu. Biệt danh được lưu trên thiết bị này để vào lại phòng.</p><form id="nicknameForm"><label for="nickname">Biệt danh</label><input id="nickname" maxlength="24" value="${esc(authed?.name||'')}" autocomplete="nickname" required><p id="authError" class="error"></p><button class="primary">Lưu biệt danh →</button></form>`);$('#nicknameForm').onsubmit=async e=>{e.preventDefault();try{await becomeGuest($('#nickname').value);closeModal();next?.();}catch(e){$('#authError').textContent=e.message;}};}
$('#account').onclick=()=>login();
function connect(code,options={}){return new Promise((resolve,reject)=>{socket?.disconnect();socket=makeSocket({auth:{token:authed.token},reconnection:true});let resolved=false;socket.on('connect',()=>{connected=true;socket.emit('join',{code,...options},r=>{if(r.error){reject(Error(r.error));return;}room=r.room;owner=r.owner;me=authed.id;if(!resolved){resolved=true;resolve(r);}else toast('Đã kết nối lại phòng.');});});socket.on('connect_error',e=>{connected=false;if(!resolved)reject(Error(e.message));});socket.on('disconnect',()=>{connected=false;keys={};touch={};if(mode==='online')toast('Mất kết nối; đang thử vào lại…');});socket.on('room',r=>{const prev=room?.phase;room=r;if(mode==='mc'){if(Date.now()-roomPaintAt>500||prev!==r.phase)showMC();}else if(['online','spectate','waiting'].includes(mode)){if(r.phase==='select'&&prev!=='select'){match=null;currentQuestion=null;$('#question').hidden=true;pickPreview=null;closeModal();mode='waiting';}if(r.phase==='battle'&&prev!=='battle'){closeModal();mode='waiting';}if(['result','finished'].includes(r.phase)&&prev!==r.phase){resultModal(r.results.at(-1),r.phase==='finished');}if(mode==='waiting')showWaiting();}});socket.on('match',m=>{match=m;match.round=room?.round;if(mode==='waiting'&&room?.phase==='battle')enterOnline();});socket.on('question',q=>{pendingQuestion=q;if(['online','spectate'].includes(mode)&&match?.players.some(p=>p.id===me))showQuestion(q);});socket.on('chat',m=>{const p=document.createElement('p');p.textContent=m.name+': '+m.text;$('#chatlog').append(p);while($('#chatlog').children.length>5)$('#chatlog').firstChild.remove();});setTimeout(()=>{if(!resolved){reject(Error('Không kết nối được máy chủ phòng chơi.'));socket.disconnect();}},12000);});}
$('#join').onclick=joinModal;
function joinModal(){
 joinRosterCode=null;joinRoster=null;
 modal(`<span class="badge">VÀO PHÒNG LỚP HỌC</span><h2>Hẹn nhau ở sảnh chờ!</h2><div class="join-steps"><b>1 · Vào phòng</b><b>2 · Chờ giáo viên</b><b>3 · Chọn tướng</b></div><form id="joinForm"><label for="joinNickname">Tên / biệt danh</label><input id="joinNickname" maxlength="24" value="${esc(authed?.role==='guest'?authed.name:'')}" placeholder="Ví dụ: Bông" autocomplete="nickname" required><label for="roomCode">Mã phòng 6 số</label><div class="room-check"><input id="roomCode" inputmode="numeric" pattern="[0-9]{6}" maxlength="6" value="${esc(new URLSearchParams(location.search).get('room')||'')}" required><button type="button" class="outline" id="checkRoom">Kiểm tra phòng</button></div><label for="joinTeam">Chọn đội của bạn</label><select id="joinTeam">${teams.map((t,i)=>`<option value="${i}">Đội ${i+1}</option>`).join('')}</select><p class="smalltext" id="joinTeamNote">Chọn số đội giáo viên đã thông báo.</p><div id="joinDetails" hidden><p id="joinRoomTitle" class="join-room-title"></p><div id="rosterChoice" hidden><label for="joinMember">Tên trong danh sách (nếu có)</label><select id="joinMember"><option value="">Dùng biệt danh đã nhập</option></select><p class="smalltext">Bạn có thể chọn tên giáo viên đã nhập sẵn trong đội.</p></div></div><label><input type="checkbox" id="spectator" style="width:auto"> Chỉ xem trận</label><p class="smalltext">Vào sảnh trước. Khi giáo viên bấm bắt đầu, bạn mới chọn và chốt tướng.</p><p class="error" id="joinError" role="alert"></p><button class="primary" id="joinSubmit">Vào sảnh chờ →</button></form>`);
 $('#joinForm').onsubmit=async e=>{e.preventDefault();const button=$('#joinSubmit');button.disabled=true;try{if(!await loadJoinRoster())return;await becomeGuest($('#joinNickname').value);await connect($('#roomCode').value,{team:+$('#joinTeam').value,rosterId:$('#joinMember').value,spectator:$('#spectator').checked});mode='waiting';pickPreview=null;closeModal();if(room.phase==='battle'&&match)enterOnline();else showWaiting();}catch(e){$('#joinError').textContent=e.message;}finally{button.disabled=false;}};
 $('#checkRoom').onclick=async()=>{if(await loadJoinRoster())$('#joinDetails').hidden=false;};
 $('#roomCode').oninput=()=>{joinRosterCode=null;joinRoster=null;$('#joinDetails').hidden=true;$('#joinTeamNote').textContent='Chọn số đội giáo viên đã thông báo.';};$('#joinTeam').onchange=()=>{if(joinRoster)renderJoinMembers();};
}
let pickPreview=null,pickBusy=false;
function heroName(id){return heroes.find(h=>h.id===id)?.name||'Chưa chọn tướng';}
function waitingTeam(team){const ps=room.players.filter(p=>p.team===team);return `<section class="mc-card waiting-team"><h3>${esc(room.teams[team])}<small>${ps.length}/5</small></h3>${ps.map(p=>`<div class="waiting-player ${p.id===me?'is-you':''}"><div class="waiting-avatar">${p.hero?`<img src="./assets/pixel/${p.hero}.png" alt="">`:'?'}</div><div><b>${esc(p.rosterName||p.name)}${p.id===me?' · Bạn':''}</b><small>${room.phase==='lobby'?'Chờ giáo viên bắt đầu':esc(heroName(p.hero))}</small></div><span class="waiting-pill ${p.heroReady?'ready':''}">${!p.approved?'Chờ duyệt':room.phase==='lobby'?'Đã vào':p.heroReady?'✓ Sẵn sàng':room.pair.includes(p.team)?'Đang chọn':'Chờ vòng sau'}</span></div>`).join('')||'<p>Đang chờ các bạn vào đội…</p>'}</section>`;}
function showWaiting(){
 if(!room)return;if(room.phase==='battle'){if(match)enterOnline();return;}
 document.body.classList.remove('playing');document.body.classList.add('mc-mode');$('#lobby').hidden=true;$('#header').hidden=false;$('#game').hidden=true;$('#mcPanel').hidden=false;scene?.setMode('lobby');
 const p=room.players.find(p=>p.id===me),selecting=room.phase==='select'&&p?.approved&&room.pair.includes(p.team),active=room.players.filter(p=>room.pair.includes(p.team)&&p.approved),ready=active.filter(p=>p.heroReady).length;
 if(selecting&&!p.heroReady&&!heroes.some(h=>h.id===pickPreview&&!room.players.some(q=>q.team===p.team&&q.id!==me&&q.heroReady&&q.hero===h.id)))pickPreview=heroes.find(h=>!room.players.some(q=>q.team===p.team&&q.id!==me&&q.heroReady&&q.hero===h.id))?.id;
 const preview=heroes.find(h=>h.id===(p?.heroReady?p.hero:pickPreview));
 $('#mcPanel').innerHTML=`<div class="mc-head"><div><span class="eyebrow">PHÒNG ${esc(room.code)} · ${esc(room.title)}</span><h1>${selecting?'Chọn bạn đồng hành!':'Sảnh chờ lớp học'}</h1><p>${room.phase==='lobby'?'Bạn đã vào phòng. Chọn tướng sẽ mở khi giáo viên bấm bắt đầu.':selecting?(p.heroReady?'Bạn đã chốt tướng. Đợi các bạn chọn xong để cùng vào trận.':'Chọn một tướng rồi bấm chốt để sẵn sàng.'):room.phase==='select'?'Hai đội đang chọn tướng. Đội bạn sẽ chọn khi tới lượt thi đấu.':'Đợi giáo viên mở vòng tiếp theo nhé.'}</p></div><button class="outline" id="waitingBack">Về sảnh</button></div><div class="waiting-journey"><span class="done">✓ Vào phòng</span><span class="${room.phase==='lobby'?'current':'done'}">${room.phase==='lobby'?'2':'✓'} Chờ giáo viên</span><span class="${selecting?'current':''}">3 Chọn tướng</span><span>4 Cùng vào trận</span></div>${room.phase==='select'?`<div class="pick-status" role="status"><b>${ready} / ${active.length} người đã sẵn sàng</b><span id="waitingStatus"></span></div>`:'<p id="waitingStatus" class="waiting-banner" role="status"></p>'}${selecting?`<div class="pick-layout"><div class="mc-card pick-main"><h3>12 người bạn · Chọn tướng của bạn</h3><p>Mỗi đội dùng một tướng một lần. Tướng đồng đội đã chốt sẽ được khóa.</p><div class="pick-hero-grid">${heroes.map(h=>{const taken=room.players.some(q=>q.team===p.team&&q.id!==me&&q.heroReady&&q.hero===h.id);return `<button type="button" class="pick-card ${h.id===(p.heroReady?p.hero:pickPreview)?'active':''}" data-pick="${h.id}" aria-pressed="${h.id===(p.heroReady?p.hero:pickPreview)}" ${taken||p.heroReady||pickBusy?'disabled':''}><img src="./assets/pixel/${h.id}.png" alt=""><b>${esc(h.name)}</b><small>${taken?'Đồng đội đã chọn':h.role}</small></button>`;}).join('')}</div></div><aside class="mc-card pick-preview"><span class="badge">${p.heroReady?'ĐÃ CHỐT TƯỚNG':'TƯỚNG BẠN CHỌN'}</span>${preview?`<img class="pick-big" src="./assets/pixel/${preview.id}.png" alt="${esc(preview.name)}"><h2>${esc(preview.name)}</h2><p>${esc(preview.role)} · ${esc(preview.title)}</p><div class="pick-spells">${[preview.skill,preview.second,'Chiêu cuối'].map((name,i)=>`<span><img src="./assets/pixel/${skillIconSet(preview)[i+1]}.png" alt=""><small>${esc(name)}</small></span>`).join('')}</div>`:''}<button class="primary" id="lockHero" ${p.heroReady||pickBusy?'disabled':''}>${p.heroReady?'✓ Đã sẵn sàng · Đợi đồng đội':pickBusy?'Đang chốt…':'Chốt tướng · Sẵn sàng →'}</button><p class="error" id="pickError" role="alert"></p><small>Chốt xong không đổi tướng trong vòng này.</small></aside></div>`:''}<div class="mc-grid waiting-teams">${room.teams.map((_,i)=>waitingTeam(i)).join('')}</div><p class="smalltext">${p?(p.approved?'Giáo viên đã duyệt bạn vào đội.':'Bạn đang chờ giáo viên duyệt vào đội.'):'Bạn đang ở chế độ khán giả.'}</p>`;
 $('#waitingBack').onclick=goLobby;$$('[data-pick]').forEach(b=>b.onclick=()=>{pickPreview=b.dataset.pick;showWaiting();});
 if($('#lockHero'))$('#lockHero').onclick=()=>{if(pickBusy||p.heroReady)return;pickBusy=true;showWaiting();socket.emit('selectHero',{hero:pickPreview},r=>{pickBusy=false;if(r.room)room=r.room;showWaiting();if(r.error&&$('#pickError'))$('#pickError').textContent=r.error;});};updateWaitingStatus();
}
function updateWaitingStatus(){if(!room)return;const status=$('#waitingStatus'),count=$('#mcCountdown');if(room.phase==='select'){const ps=room.players.filter(p=>room.pair.includes(p.team)&&p.approved),ready=ps.filter(p=>p.heroReady).length,text=room.selectionEnds?`Tất cả đã chốt · Cùng vào trận sau ${Math.max(0,Math.ceil((room.selectionEnds-Date.now())/1000))} giây`:`Đang chờ ${ps.length-ready} bạn chốt tướng. Trận chưa bắt đầu.`;if(status)status.textContent=text;if(count)count.textContent=`Chọn tướng: ${ready}/${ps.length} · ${text}`;}else if(status)status.textContent=room.phase==='lobby'?'Hãy đợi giáo viên bấm bắt đầu. Bạn chưa cần chọn tướng.':'Đang chờ giáo viên mở vòng tiếp theo.';}
function enterOnline(){closeModal();mode=match?.players.some(p=>p.id===me)?'online':'spectate';cameraMode=mode==='spectate'?'spectate':'battle';gameVisible();if(mode==='online'&&pendingQuestion&&match.time-pendingQuestion.at<=10)showQuestion(pendingQuestion);toast(mode==='spectate'?'Bạn đang xem trận trực tiếp.':'Trận đấu đã bắt đầu!');}
$('#chatForm').onsubmit=e=>{e.preventDefault();const text=$('#chatInput').value.trim();if(!text)return;if(mode==='demo')toast('Chat đội hoạt động trong phòng online.');else socket?.emit('chat',text,r=>{if(r.error)toast(r.error);});$('#chatInput').value='';$('#chatInput').blur();};
$('#mc').onclick=()=>{location.href='./mc.html';};
async function openMC(){try{await becomeHost();const rooms=await api('/api/rooms');modal(`<span class="badge">BÀN ĐIỀU KHIỂN GIÁO VIÊN</span><h2>Tạo một sân chơi mới.</h2><form id="createForm"><label>Tên giải đấu</label><input id="tournamentTitle" value="Giải đấu Học viện" maxlength="80"><p class="smalltext">Không cần đăng nhập. Quyền MC của phòng được lưu riêng trên trình duyệt này; học sinh chỉ có thể xin vào bằng biệt danh.</p><p class="error" id="createError"></p><button class="primary">Tạo phòng mới →</button></form>${rooms.length?`<label>Hoặc mở giải đã lưu</label><select id="savedRooms">${rooms.map(r=>`<option value="${r.code}">${esc(r.title)} · ${r.code}</option>`).join('')}</select><button class="textbtn" id="resumeRoom">Mở giải →</button>`:''}`);$('#createForm').onsubmit=async e=>{e.preventDefault();try{const r=await api('/api/rooms',{title:$('#tournamentTitle').value});await connect(r.code);bank=await api('/api/bank');mode='mc';closeModal();showMC();}catch(e){$('#createError').textContent=e.message;}};if($('#resumeRoom'))$('#resumeRoom').onclick=async()=>{try{await connect($('#savedRooms').value);bank=await api('/api/bank');mode='mc';closeModal();showMC();}catch(e){toast(e.message);}};}catch(e){toast(e.message);}}
async function command(action,extra={}){return new Promise(resolve=>socket.emit('mc',{action,...extra},r=>{if(r.error)toast(r.error);else if(r.room){room=r.room;showMC();}resolve(r);}));}
function showMC(){if(!room)return;roomPaintAt=Date.now();document.body.classList.remove('playing');document.body.classList.add('mc-mode');$('#lobby').hidden=true;$('#header').hidden=false;$('#game').hidden=true;$('#mcPanel').hidden=false;scene?.setMode('lobby');const phase={lobby:'Sảnh chờ',select:'Học sinh đang chọn tướng',battle:'Đang thi đấu',result:'Kết thúc trận',finished:'Kết thúc giải'}[room.phase],url=location.origin+'/player.html?room='+room.code,round=room.phase==='result'?room.round+1:room.round;
 $('#mcPanel').innerHTML=`<div class="mc-head"><div><span class="eyebrow">BÀN ĐIỀU KHIỂN GIÁO VIÊN</span><h1>${esc(room.title)}</h1><span class="statuspill">${phase}${room.paused?' · Tạm dừng':''}</span></div><div><button class="outline" id="mcOther">Các giải đấu</button><button class="outline" id="mcHome">Về sảnh</button></div></div><div class="mc-grid"><div class="mc-card"><h3>Mời học sinh vào học viện</h3><div class="formrow"><div><div class="roomcode">${room.code}</div><p>Quét bằng camera hoặc Zalo, nhập biệt danh và chọn đội. Không cần tài khoản. Không cần cùng Wi-Fi khi dùng link online.</p><button class="outline" id="copyRoom">Sao chép link</button></div><div id="qrHere" style="flex:0 0 132px"></div></div><p class="smalltext">${esc(url)}</p></div><div class="mc-card"><h3>Điều khiển giải đấu</h3><p>Bán kết 1: hạng 1–4 · Bán kết 2: hạng 2–3 · Chung kết: hai đội thắng. Mặc định thứ hạng theo số đội; có thể chỉnh trước giải.</p><button class="primary" id="startRound" ${!['lobby','result'].includes(room.phase)?'disabled':''}>${room.phase==='result'?'Mở chọn tướng vòng kế tiếp':'Bắt đầu · Mở chọn tướng'}</button><button class="outline" id="rosterEdit" ${room.phase!=='lobby'?'disabled':''}>Tên đội & thành viên</button><button class="outline" id="roomSettings" ${room.phase!=='lobby'?'disabled':''}>Cấu hình thời gian</button><button class="outline" id="fillBots" ${room.phase!=='lobby'?'disabled':''}>Điền người máy</button><button class="outline" id="pauseMatch" ${room.phase!=='battle'?'disabled':''}>${room.paused?'Tiếp tục':'Tạm dừng'}</button><button class="outline" id="endMatch" ${room.phase!=='battle'?'disabled':''}>Kết thúc trận</button><button class="outline" id="watchMatch" ${!match||room.phase!=='battle'?'disabled':''}>Xem trên máy chiếu</button><button class="outline" id="replay" ${!['finished','result'].includes(room.phase)?'disabled':''}>Lưu giải & chơi lại</button><p id="mcCountdown" class="smalltext"></p></div>
 ${room.teams.map((t,i)=>`<div class="mc-card"><h3>${esc(t)} <small>(${room.players.filter(p=>p.team===i).length}/5)</small></h3>${room.phase==='lobby'?`<div class="formrow"><div><label>Tên đội</label><input data-teamname="${i}" value="${esc(t)}" maxlength="24"></div><div><label>Hạng trước giải</label><select data-seed="${i}">${[0,1,2,3].map(rank=>`<option value="${rank}" ${room.seed[rank]===i?'selected':''}>${rank+1}</option>`).join('')}</select></div></div>`:''}${room.players.filter(p=>p.team===i).map(p=>`<div class="mc-player"><span>${esc(p.rosterName||p.name)}${p.rosterName?' ('+esc(p.name)+')':''} · ${esc(heroName(p.hero))}</span>${p.approved?'<span style="color:#bce9cc">✓ Đã duyệt</span>':`<button class="outline" data-approve="${p.id}">Duyệt</button>`}</div>`).join('')||'<p>Chưa có học sinh.</p>'}${i===3&&room.phase==='lobby'?'<button class="outline" id="saveTeams">Lưu tên đội & xếp hạng</button>':''}</div>`).join('')}
 <div class="mc-card wide"><h3>Ngân hàng câu hỏi <span class="badge">${bank.length} CÂU</span></h3><p>Câu hỏi chỉ mở khi từng người bị hạ gục hoặc vừa lên cấp. Chọn câu cho bộ của vòng, hoặc để trống để dùng cả bộ. Không có câu hỏi định kỳ; số câu tùy diễn biến chiến đấu. Ngân hàng mặc định gồm 60 câu thực tế và 140 bài tính ứng dụng.</p><div class="formrow"><div><label>Tìm câu hỏi</label><input id="bankSearch" placeholder="Nhập nội dung hoặc chủ đề"></div><div><label>Vòng</label><select id="bankRound">${['Bán kết 1','Bán kết 2','Chung kết','Dự phòng'].map((v,i)=>`<option value="${i}" ${i===round?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Độ khó</label><select id="bankDiff"><option>Tất cả</option><option>Dễ</option><option>Trung bình</option><option>Khó</option></select></div></div><div class="question-list" id="bankList"></div><button class="outline" id="importBank">Tải câu hỏi Excel</button><button class="outline" id="sampleExcel">Tải mẫu Excel</button><input id="bankFile" type="file" accept=".xlsx,.xls" hidden><p class="smalltext">Chỉ sửa câu do máy chủ này tải lên; các câu mặc định có thể thay bằng bộ Excel riêng.</p></div>
 <div class="mc-card wide"><h3>Kết quả & lịch sử</h3>${room.results.length?`<table><thead><tr><th>Trận</th><th>Đội thắng</th><th>MVP</th><th>Điểm</th></tr></thead><tbody>${room.results.map((r,i)=>`<tr><td>${i<2?'Bán kết '+(i+1):'Chung kết'}</td><td>${r.winner===null?'Hòa':esc(room.teams[r.winner])}</td><td>${esc(r.mvp)}</td><td>${r.scores.map(s=>s.total.toFixed(2)).join(' / ')}</td></tr>`).join('')}</tbody></table>`:'<p>Chưa có kết quả.</p>'}<button class="outline" id="exportExcel">Xuất Excel</button><button class="outline" id="exportPDF">In / Lưu PDF</button><button class="outline" id="adjustPoints" ${!match?'disabled':''}>Chỉnh điểm có lịch sử</button><button class="outline" id="viewArchives">Xem giải đã lưu</button>${room.history.slice(-5).map(h=>`<p class="smalltext">${esc(h.student)} · ${h.delta>0?'+':''}${h.delta} · ${esc(h.reason)} · ${esc(h.at)}</p>`).join('')}</div></div>`;
 QRCode.toCanvas(document.createElement('canvas'),url,{width:130,margin:1,errorCorrectionLevel:'M'},(e,c)=>{if(!e)$('#qrHere')?.append(c);});
 $('#mcHome').onclick=goLobby;$('#mcOther').onclick=openMC;$('#copyRoom').onclick=()=>navigator.clipboard.writeText(url).then(()=>toast('Đã sao chép link học sinh.')).catch(()=>toast(url));$('#startRound').onclick=()=>{const ids=$$('[data-qid]:checked').map(x=>x.dataset.qid);command('start',{questionIds:ids});};$('#rosterEdit').onclick=editRoster;$('#roomSettings').onclick=editRoomSettings;$('#fillBots').onclick=()=>command('bots');$('#pauseMatch').onclick=()=>command('pause');$('#endMatch').onclick=()=>confirmModal('Kết thúc trận hiện tại?','Kết quả sẽ được chốt theo điểm hiện tại.',()=>command('finish'));$('#watchMatch').onclick=()=>{mode='spectate';cameraMode='spectate';gameVisible();};$('#replay').onclick=()=>confirmModal('Lưu giải và chơi lại?','Kết quả cũ sẽ nằm trong mục Giải đã lưu; phòng chuyển về sảnh.',()=>command('replay'));$$('[data-approve]').forEach(b=>b.onclick=()=>command('approve',{id:b.dataset.approve}));
 if($('#saveTeams'))$('#saveTeams').onclick=()=>{const ts=$$('[data-teamname]').map(x=>x.value),seed=[];$$('[data-seed]').forEach(x=>seed[+x.value]=+x.dataset.seed);if(seed.length!==4||seed.some(x=>x===undefined)||new Set(seed).size!==4)return toast('Mỗi đội cần một thứ hạng khác nhau.');command('setup',{teams:ts,seed});};
 const chosen=new Set();function drawBank(){const search=$('#bankSearch').value.toLowerCase(),round=+$('#bankRound').value,diff=$('#bankDiff').value;$('#bankList').innerHTML=bank.filter(q=>q.round===round&&(diff==='Tất cả'||q.difficulty===diff)&&(q.text+' '+q.topic).toLowerCase().includes(search)).map(q=>`<div class="bank-row"><input type="checkbox" data-qid="${q.id}" ${chosen.has(q.id)?'checked':''}><span>${esc(q.text)} <em>${q.answer?'Đúng':'Sai'} · ${esc(q.difficulty)} · ${esc(q.topic)}</em></span>${q.owner===authed.id?`<button data-edit="${q.id}">Sửa</button>`:''}</div>`).join('');$$('[data-qid]').forEach(x=>x.onchange=()=>{if(x.checked)chosen.add(x.dataset.qid);else chosen.delete(x.dataset.qid);});$$('[data-edit]').forEach(b=>b.onclick=()=>editQuestion(b.dataset.edit));}$('#bankSearch').oninput=drawBank;$('#bankRound').onchange=()=>{chosen.clear();drawBank();};$('#bankDiff').onchange=drawBank;drawBank();
 $('#importBank').onclick=()=>$('#bankFile').click();$('#bankFile').onchange=async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1e6)return toast('File tối đa 1 MB.');try{const buf=new Uint8Array(await f.arrayBuffer());let binary='';for(const byte of buf)binary+=String.fromCharCode(byte);const r=await api('/api/import',{base64:btoa(binary)});bank=await api('/api/bank');toast('Đã thêm '+r.count+' câu hỏi.');showMC();}catch(e){toast(e.message);}};
 $('#sampleExcel').onclick=()=>{loadXLSX().then(XLSX=>{const wb=XLSX.utils.book_new();XLSX.utils.book_append_sheet(wb,XLSX.utils.json_to_sheet([{CauHoi:'Không cung cấp mã OTP cho người lạ.',DapAn:true,Vong:0,DoKho:'Dễ',ChuDe:'An toàn số'},{CauHoi:'HTTPS bảo đảm mọi website đều đáng tin.',DapAn:false,Vong:0,DoKho:'Trung bình',ChuDe:'An toàn số'}]),'CauHoi');XLSX.writeFile(wb,'mau-cau-hoi.xlsx');});};$('#exportExcel').onclick=async()=>{try{const r=await fetch('/api/export/'+room.code,{headers:{Authorization:'Bearer '+authed.token}});if(!r.ok)throw Error('Không xuất được kết quả.');download(await r.blob(),'arcana-'+room.code+'.xlsx');}catch(e){toast(e.message);}};$('#exportPDF').onclick=printResults;$('#adjustPoints').onclick=adjustModal;$('#viewArchives').onclick=async()=>{try{const rs=await api('/api/archives/'+room.code);modal(`<h2>Giải đấu đã lưu</h2>${rs.length?rs.map((a,i)=>`<p><b>Giải ${i+1}</b> · ${esc(a.at)}<br>${a.results.map((r,j)=>`Trận ${j+1}: ${r.winner===null?'Hòa':esc(room.teams[r.winner])} · MVP ${esc(r.mvp)}`).join('<br>')}</p>`).join(''):'<p>Chưa có giải cũ. Dùng “Lưu giải & chơi lại” sau khi thi đấu.</p>'}`);}catch(e){toast(e.message);}};
}
function confirmModal(title,text,action){modal(`<h2>${esc(title)}</h2><p>${esc(text)}</p><button class="primary" id="confirmAction">Xác nhận</button>`);$('#confirmAction').onclick=()=>{closeModal();action();};}
function editQuestion(id){const q=bank.find(q=>q.id===id);modal(`<h2>Sửa câu hỏi</h2><label>Nội dung</label><input id="editQ" value="${esc(q.text)}" maxlength="500"><label>Đáp án</label><select id="editA"><option value="true" ${q.answer?'selected':''}>Đúng</option><option value="false" ${!q.answer?'selected':''}>Sai</option></select><button class="primary" id="saveQuestion">Lưu câu hỏi</button>`);$('#saveQuestion').onclick=async()=>{try{await api('/api/bank/'+id,{text:$('#editQ').value,answer:$('#editA').value==='true'},'PATCH');bank=await api('/api/bank');closeModal();showMC();}catch(e){toast(e.message);}};}
function adjustModal(){modal(`<h2>Điều chỉnh điểm</h2><label>Học sinh trong trận</label><select id="adjustId">${match.players.map(p=>`<option value="${p.id}">${esc(p.name)} · ${p.knowledge} điểm</option>`).join('')}</select><label>Số điểm cộng/trừ</label><input id="adjustDelta" type="number" min="-1000" max="1000" value="10"><label>Lý do (bắt buộc)</label><input id="adjustReason" maxlength="200"><button class="primary" id="saveAdjustment">Ghi lịch sử & áp dụng</button>`);$('#saveAdjustment').onclick=async()=>{const r=await command('adjust',{id:$('#adjustId').value,delta:+$('#adjustDelta').value,reason:$('#adjustReason').value});if(!r.error)closeModal();};}
function loadXLSX(){if(window.XLSX)return Promise.resolve(window.XLSX);return new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='./vendor/xlsx.js';s.onload=()=>resolve(window.XLSX);s.onerror=()=>reject(Error('Không tải được công cụ Excel.'));document.head.append(s);});}
function download(blob,name){const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000);}
function printResults(){const old=$('.print-only');old?.remove();const el=document.createElement('div');el.className='print-only';el.innerHTML=`<h1 style="font:24px Arial">ARCANA — ${esc(room.title)}</h1><p>Phòng ${room.code} · ${new Date().toLocaleString('vi-VN')}</p><table><tr><th>Trận</th><th>Biệt danh</th><th>Đội</th><th>Đúng</th><th>Điểm kiến thức</th><th>Hạ gục</th></tr>${room.results.flatMap((r,i)=>r.players.map(p=>`<tr><td>${i+1}</td><td>${esc(p.name)}</td><td>${esc(room.teams[p.team])}</td><td>${p.correct}</td><td>${p.knowledge}</td><td>${p.kills}</td></tr>`)).join('')}</table><h3>Lịch sử điều chỉnh</h3>${room.history.map(h=>`<p>${esc(h.at)} · ${esc(h.student)} · ${h.delta} · ${esc(h.reason)}</p>`).join('')}`;document.body.append(el);window.print();}
function frame(now){const dt=Math.min((now-last)/1000,.5);last=now;try{if(mode==='demo'&&match&&!match.done&&!demoPaused&&!portraitBlocked()){const p=match.players.find(p=>p.id===me);p.input=$('#modal').hidden?input():{};for(const b of match.players)if(b.bot)b.input=botInput(match,b);for(let elapsed=0;elapsed<dt;elapsed+=.05)step(match,Math.min(.05,dt-elapsed));pumpQuizzes(match,questions,(player,q)=>{if(player.id===me)showQuestion(q);});for(const bot of match.players)if(bot.bot&&bot.quiz&&!bot.quiz.resolved&&match.time-bot.quiz.at>=3)answerQuiz(match,bot,bot.quiz.index,Math.random()<.72?bot.quiz.answer:!bot.quiz.answer);if(match.done){const out=result(match);demoHistory.push({at:new Date().toISOString(),...out});localStorage.setItem('arcana-history',JSON.stringify(demoHistory.slice(-20)));resultModal(out);}}
 if(mode==='online'&&connected&&now-sendAt>50){sendAt=now;socket?.emit('input',$('#modal').hidden&&!portraitBlocked()?input():{});}if(now-uiAt>100){uiAt=now;if(['demo','online','spectate'].includes(mode))updateHUD();updateWaitingStatus();}const cameraPlayer=match?.players?.find(p=>p.id===me);cameraControl?.setActive(['demo','online'].includes(mode),cameraPlayer&&match.pair.indexOf(cameraPlayer.team)===1?1:0);updateMusic();scene?.render(match,me,now/1000);}catch(e){console.error(e);}requestAnimationFrame(frame);}
try{scene=makePixelScene($('#world'),viewCameraState);cameraControl=scene.controls;cameraControl.onChange=updateCameraLabel;updateCameraLabel();scene.setMode('lobby');$('#loading').hidden=true;requestAnimationFrame(frame);}catch(e){$('#loading').innerHTML=`<b>Không mở được đấu trường pixel</b><p>${esc(e.message)}</p>`;}
if(hostEdition)setTimeout(openMC,300);else if(playerEdition||new URLSearchParams(location.search).has('room'))setTimeout(joinModal,300);

function updateCameraLabel(){if($('#cameraToggle')){$('#cameraToggle').textContent=viewCameraState.free?'▣ Camera tự do · V':'▣ Theo nhân vật · V';$('#cameraToggle').setAttribute('aria-pressed',String(viewCameraState.free));}if($('#cameraHint'))$('#cameraHint').textContent='Góc nhìn 2D · kéo để xem bản đồ · cuộn / chụm để zoom';}
$('#cameraToggle').onclick=()=>cameraControl?.toggle();$('#cameraReset').onclick=()=>{cameraControl?.reset();toast('Camera đã về nhân vật.');};$('#zoomIn').onclick=()=>cameraControl?.zoom(-180);$('#zoomOut').onclick=()=>cameraControl?.zoom(180);
$('#toggleScores').onclick=()=>{document.body.classList.toggle('scoreboard-hidden');$('#toggleScores').setAttribute('aria-expanded',String(!document.body.classList.contains('scoreboard-hidden')));};
function showVideo(){if(mode==='demo')demoPaused=true;modal(`<span class="badge">HƯỚNG DẪN CHO NGƯỜI MỚI</span><h2>Xem một lần, vào trận luôn.</h2><video controls playsinline preload="metadata" style="width:100%;border-radius:8px;background:#0a1625" src="./media/huong-dan-arcana.mp4"></video><p>Video minh họa có chữ tiếng Việt và dấu chỉ thao tác. Có thể dừng hoặc tua lại bất cứ lúc nào.</p><p class="smalltext">00:00 Bắt đầu · 00:08 Chọn tướng · 00:18 Camera · 00:33 Di chuyển · 00:43 Kỹ năng · 00:55 Câu hỏi · 01:10 Hồi phục · 01:20 Vào lớp học</p><p class="smalltext">Luật mới: hạ đối thủ mới lên cấp; câu hỏi chỉ hiện khi lên cấp hoặc bị hạ gục. Video minh họa cách bấm, hình ảnh thuộc bản trước.</p>`);}
$('#videoGuide').onclick=showVideo;$('#videoGame').onclick=showVideo;

const joystick=makeJoystick($('#joystick'),v=>{touchAnalog=v;});
window.addEventListener('blur',()=>{touchAnalog={forward:0,right:0};});
document.addEventListener('visibilitychange',()=>{if(document.hidden){bgm.pause();joystick.reset();}else if(soundOn)bgm.play().catch(()=>{});});
$('#fullscreen').onclick=async()=>{try{await document.documentElement.requestFullscreen?.();await screen.orientation?.lock?.('landscape');}catch{toast('Hãy xoay điện thoại ngang; trình duyệt này không khóa xoay tự động.');}};
$('#portraitHelp').onclick=()=>toast('Tắt khóa xoay của điện thoại rồi đặt máy nằm ngang để chơi.');
for(const label of $$('.brand>div'))label.innerHTML=esc(customization.brand.name)+`<small>${esc(customization.brand.subtitle)}</small>`;
