for(const [name,key]of [['--mint','accent'],['--gold','gold']])document.documentElement.style.setProperty(name,customization.theme[key]);

let joinRosterCode=null,joinRoster=null;
async function loadJoinRoster(){try{const code=$('#roomCode').value;if(!/^\d{6}$/.test(code))throw Error('Nhập mã phòng 6 số.');if(joinRosterCode!==code){const team=$('#joinTeam').value;joinRoster=await api('/api/room-info/'+code);joinRosterCode=code;$('#joinTeam').innerHTML=joinRoster.teams.map((name,i)=>`<option value="${i}">${i+1} · ${esc(name)}</option>`).join('');$('#joinTeam').value=team;renderJoinMembers();}$('#joinRoomTitle').textContent='Phòng '+joinRoster.code+' · '+joinRoster.title;$('#joinTeamNote').textContent='Đội bạn chọn: '+joinRoster.teams[+$('#joinTeam').value];$('#joinError').textContent='';return true;}catch(e){$('#joinError').textContent=e.message;return false;}}
function renderJoinMembers(){const team=+$('#joinTeam').value,rows=joinRoster.roster.filter(row=>row.team===team);$('#rosterChoice').hidden=!rows.length;$('#joinMember').innerHTML='<option value="">Dùng tên / biệt danh đã nhập</option>'+rows.map(row=>`<option value="${esc(row.id)}" ${row.claimedBy&&row.claimedBy!==authed?.id?'disabled':''}>${esc(row.name)}${row.claimedBy&&row.claimedBy!==authed?.id?' — đã vào':''}</option>`).join('');$('#joinTeamNote').textContent='Đội bạn chọn: '+joinRoster.teams[team];}
function editRoster(){const roster=room.roster||[];modal(`<span class="badge">GIÁO VIÊN CHIA ĐỘI</span><h2>Tên đội và thành viên</h2><p>Mỗi đội tối đa 5 người. Để trống những ô chưa dùng. Học sinh tự chọn đội và biệt danh; có thể chọn tên sẵn trong đội. MC duyệt trước khi chơi.</p><div class="roster-grid">${room.teams.map((name,team)=>`<div class="roster-team"><label>Tên đội ${team+1}</label><input data-roster-team="${team}" value="${esc(name)}" maxlength="24">${Array.from({length:5},(_,i)=>{const entry=roster.filter(row=>row.team===team)[i];return `<input data-roster-name="${team}" data-slot-id="${esc(entry?.id||'')}" value="${esc(entry?.name||'')}" placeholder="Thành viên ${i+1}" maxlength="24">`;}).join('')}</div>`).join('')}</div><p id="rosterError" class="error"></p><button class="primary" id="saveRoster">Lưu đội & danh sách</button>`);$('#saveRoster').onclick=async()=>{const rows=$$('[data-roster-name]').map(el=>({id:el.dataset.slotId||undefined,name:el.value,team:Number(el.dataset.rosterName)}));const first=await command('roster',{rows});if(first.error){$('#rosterError').textContent=first.error;return;}const second=await command('setup',{teams:$$('[data-roster-team]').map(el=>el.value)});if(!second.error){closeModal();toast('Đã lưu đội và thành viên.');}};}
function editRoomSettings(){modal(`<span class="badge">CẤU HÌNH TRƯỚC GIẢI</span><h2>Thời gian thi đấu</h2><div class="settings-row"><div><label>Bán kết (giây)</label><input type="number" min="60" max="1800" id="semiSeconds" value="${room.settings?.semiSeconds||customization.match.semiSeconds}"></div><div><label>Chung kết (giây)</label><input type="number" min="60" max="1800" id="finalSeconds" value="${room.settings?.finalSeconds||customization.match.finalSeconds}"></div></div><p>Tên game, màu, nhạc và thông số tướng thay trong <b>public/config/game.json</b> trước khi triển khai bộ game.</p><p class="error" id="settingsError"></p><button class="primary" id="saveRoomSettings">Lưu cấu hình</button>`);$('#saveRoomSettings').onclick=async()=>{const r=await command('settings',{semiSeconds:Number($('#semiSeconds').value),finalSeconds:Number($('#finalSeconds').value)});if(r.error)$('#settingsError').textContent=r.error;else closeModal();};}
